// t28_bitmanip : Zba and Zbb against a model (generated by
// tools/gen_t28.py; do not edit, run the script again)
//
//   1 every instruction (and the immediates that matter) over the 8 edge
//     values (every pair of them for two operands) and 32 pairs from
//     xorshift64; the results go into
//     a checksum (rotate left by 5, xor, multiply; no Zba / Zbb) that is
//     compared with the one the script computed. Check n is entry n - 2
//     of the table, which names the instruction.
//   2 the encodings next to the new ones still trap as illegal
#include "test.h"

// x23 = (rotl(x23, 5) ^ x12) * x30 (x30 = an odd constant)
#define MIX slli x29, x23, 5; srli x23, x23, 59; or x23, x23, x29; xor x23, x23, x12; mul x23, x23, x30

    .section .text.init
    .globl _start
_start:
    TEST_INIT
    la   x20, table
    li   x30, 0x9e3779b97f4a7c15
    la   x27, edges
    li   gp, 2
next_op:
    ld   x21, 0(x20)                  // the subroutine, 0 at the end
    beqz x21, part2
    ld   x22, 8(x20)                  // the expected checksum
    ld   x28, 16(x20)                 // how many second operands * 8
    li   x23, 0
    li   x25, 0                       // a: edge index * 8
1:  li   x26, 0                       // b
2:  add  x29, x27, x25
    ld   x10, 0(x29)
    add  x29, x27, x26
    ld   x11, 0(x29)
    jalr ra, 0(x21)
    MIX
    addi x26, x26, 8
    bne  x26, x28, 2b
    addi x25, x25, 8
    li   x29, 64
    bne  x25, x29, 1b
    li   x24, 0x2545f4914f6cdd1d
    li   x25, 0                       // k
3:  call xs
    mv   x10, x24
    call xs
    mv   x11, x24
    andi x29, x25, 1
    beqz x29, 4f
    andi x29, x10, 63
    srl  x10, x10, x29
4:  jalr ra, 0(x21)
    MIX
    addi x25, x25, 1
    li   x29, 32
    bne  x25, x29, 3b
    bne  x23, x22, fail
    addi x20, x20, 24
    addi gp, gp, 1
    j    next_op

    // x24 = xorshift64(x24)
xs:
    slli x29, x24, 13
    xor  x24, x24, x29
    srli x29, x24, 7
    xor  x24, x24, x29
    slli x29, x24, 17
    xor  x24, x24, x29
    ret

    // the instructions under test
op0: add.uw    x12, x10, x11
    ret
op1: sh1add    x12, x10, x11
    ret
op2: sh2add    x12, x10, x11
    ret
op3: sh3add    x12, x10, x11
    ret
op4: sh1add.uw x12, x10, x11
    ret
op5: sh2add.uw x12, x10, x11
    ret
op6: sh3add.uw x12, x10, x11
    ret
op7: slli.uw   x12, x10, 0
    ret
op8: slli.uw   x12, x10, 1
    ret
op9: slli.uw   x12, x10, 63
    ret
op10: slli.uw   x12, x10, 62
    ret
op11: slli.uw   x12, x10, 32
    ret
op12: slli.uw   x12, x10, 9
    ret
op13: andn      x12, x10, x11
    ret
op14: orn       x12, x10, x11
    ret
op15: xnor      x12, x10, x11
    ret
op16: min       x12, x10, x11
    ret
op17: minu      x12, x10, x11
    ret
op18: max       x12, x10, x11
    ret
op19: maxu      x12, x10, x11
    ret
op20: rol       x12, x10, x11
    ret
op21: ror       x12, x10, x11
    ret
op22: rolw      x12, x10, x11
    ret
op23: rorw      x12, x10, x11
    ret
op24: rori      x12, x10, 0
    ret
op25: rori      x12, x10, 1
    ret
op26: rori      x12, x10, 63
    ret
op27: rori      x12, x10, 62
    ret
op28: rori      x12, x10, 32
    ret
op29: rori      x12, x10, 49
    ret
op30: roriw     x12, x10, 0
    ret
op31: roriw     x12, x10, 1
    ret
op32: roriw     x12, x10, 31
    ret
op33: roriw     x12, x10, 30
    ret
op34: roriw     x12, x10, 16
    ret
op35: roriw     x12, x10, 6
    ret
op36: clz       x12, x10
    ret
op37: ctz       x12, x10
    ret
op38: cpop      x12, x10
    ret
op39: clzw      x12, x10
    ret
op40: ctzw      x12, x10
    ret
op41: cpopw     x12, x10
    ret
op42: sext.b    x12, x10
    ret
op43: sext.h    x12, x10
    ret
op44: zext.h    x12, x10
    ret
op45: orc.b     x12, x10
    ret
op46: rev8      x12, x10
    ret

    //--------------------------------------------------------------
    // 2 the neighbours of the new encodings are still illegal
    //--------------------------------------------------------------
part2:
    la   t0, h_ill
    csrw mtvec, t0
    li   x28, 0
    .word 0x0815c53b                  // packw (zext.h with rs2 = 1, Zbkb)
    .word 0x60359513                  // clz family, rs2 field 3 (not defined)
    .word 0x60659513                  // clz family, rs2 field 6 (not defined)
    .word 0x6035951b                  // clzw family, rs2 field 3
    .word 0x6045951b                  // sext.b in OP-IMM-32 (not defined)
    .word 0x2885d513                  // orc.b with a different rs2 field
    .word 0x6b95d513                  // rev8 with a different rs2 field
    .word 0x4805d513                  // OP-IMM 101 with funct6 010010 (bexti of Zbs)
    .word 0x48c59533                  // OP 001 funct7 0100100 (bclr of Zbs)
    li   gp, 90
    li   t6, 9
    bne  x28, t6, fail
    TEST_DONE

    // an illegal instruction: count it, go on behind it
h_ill:
    csrr t0, mcause
    li   t6, 2
    li   gp, 91
    bne  t0, t6, fail
    addi x28, x28, 1
    csrr t0, mepc
    addi t0, t0, 4
    csrw mepc, t0
    mret

    TEST_FAIL_HANDLER

    .section .data
    .align 3
edges:
    .dword 0x0000000000000000
    .dword 0x0000000000000001
    .dword 0xffffffffffffffff
    .dword 0x8000000000000000
    .dword 0x7fffffffffffffff
    .dword 0x00000000ffffffff
    .dword 0x0000000080000000
    .dword 0x00ff00ff80007f80
table:                  // subroutine, checksum, second operands * 8
    .dword op0, 0x87fa8c73f1b7e359, 64    // 2: add.uw    x12, x10, x11
    .dword op1, 0xf106ddb7682c5cf9, 64    // 3: sh1add    x12, x10, x11
    .dword op2, 0x776ce2b58a11e848, 64    // 4: sh2add    x12, x10, x11
    .dword op3, 0x5a0e7ab682834a8d, 64    // 5: sh3add    x12, x10, x11
    .dword op4, 0x833a4b9a4a360d2c, 64    // 6: sh1add.uw x12, x10, x11
    .dword op5, 0x585cba345e030695, 64    // 7: sh2add.uw x12, x10, x11
    .dword op6, 0xc677935f69e3c43c, 64    // 8: sh3add.uw x12, x10, x11
    .dword op7, 0x6c3e6b700bc1f507,  8    // 9: slli.uw   x12, x10, 0
    .dword op8, 0xa0934d19ce709828,  8    // 10: slli.uw   x12, x10, 1
    .dword op9, 0x090d304dff410472,  8    // 11: slli.uw   x12, x10, 63
    .dword op10, 0x22ef87f368c23e01,  8    // 12: slli.uw   x12, x10, 62
    .dword op11, 0x0a297d17200beb44,  8    // 13: slli.uw   x12, x10, 32
    .dword op12, 0x5aaee3597b8ac4e7,  8    // 14: slli.uw   x12, x10, 9
    .dword op13, 0xbbed283fa83664c2, 64    // 15: andn      x12, x10, x11
    .dword op14, 0x4cdd0bd9a558a786, 64    // 16: orn       x12, x10, x11
    .dword op15, 0x77282da26de81607, 64    // 17: xnor      x12, x10, x11
    .dword op16, 0x9709e4438bfe1a6c, 64    // 18: min       x12, x10, x11
    .dword op17, 0x3780b3fdb8fac49f, 64    // 19: minu      x12, x10, x11
    .dword op18, 0x588e955142dfc58a, 64    // 20: max       x12, x10, x11
    .dword op19, 0x34f2aa3aa365117b, 64    // 21: maxu      x12, x10, x11
    .dword op20, 0x971b4707d88fe9ba, 64    // 22: rol       x12, x10, x11
    .dword op21, 0x8c817228b5114e9d, 64    // 23: ror       x12, x10, x11
    .dword op22, 0xe2ef924d9318042a, 64    // 24: rolw      x12, x10, x11
    .dword op23, 0xf1b49d476080bc05, 64    // 25: rorw      x12, x10, x11
    .dword op24, 0x4c75bf2e45ad0f7e,  8    // 26: rori      x12, x10, 0
    .dword op25, 0x2600a2e48c1a8c95,  8    // 27: rori      x12, x10, 1
    .dword op26, 0x115d9bf8e59ba7e7,  8    // 28: rori      x12, x10, 63
    .dword op27, 0xa52afd8939bbae31,  8    // 29: rori      x12, x10, 62
    .dword op28, 0xc6c0d96e7bb58c70,  8    // 30: rori      x12, x10, 32
    .dword op29, 0x35ce91d1abad1dd5,  8    // 31: rori      x12, x10, 49
    .dword op30, 0xcd102474f93c52d9,  8    // 32: roriw     x12, x10, 0
    .dword op31, 0x330af3edcc50fc09,  8    // 33: roriw     x12, x10, 1
    .dword op32, 0x999fbb02a9ef0901,  8    // 34: roriw     x12, x10, 31
    .dword op33, 0x73c5f89f55831833,  8    // 35: roriw     x12, x10, 30
    .dword op34, 0xd3d8e39cd14acced,  8    // 36: roriw     x12, x10, 16
    .dword op35, 0xec2f76eab875f033,  8    // 37: roriw     x12, x10, 6
    .dword op36, 0xc00dd7f6cb063790,  8    // 38: clz       x12, x10
    .dword op37, 0xf5082b450ee94c17,  8    // 39: ctz       x12, x10
    .dword op38, 0xbe373e8e59c17940,  8    // 40: cpop      x12, x10
    .dword op39, 0x73c71d4f4a8314f1,  8    // 41: clzw      x12, x10
    .dword op40, 0x0b942e00f496b686,  8    // 42: ctzw      x12, x10
    .dword op41, 0x02fa0ba498e24b77,  8    // 43: cpopw     x12, x10
    .dword op42, 0xc1ceff3f53546731,  8    // 44: sext.b    x12, x10
    .dword op43, 0x2340d83a0d5589db,  8    // 45: sext.h    x12, x10
    .dword op44, 0xb7ea38eb945d06de,  8    // 46: zext.h    x12, x10
    .dword op45, 0x0b40f6b75418222d,  8    // 47: orc.b     x12, x10
    .dword op46, 0x0d3d3a9eca489dba,  8    // 48: rev8      x12, x10
    .dword 0, 0, 0

    TOHOST_SECTION
